<?php
declare(strict_types=1);

require_once __DIR__.'/../lib/safety_vote_gallery.php';
require_once __DIR__.'/../lib/safety_vote_participation_authorization.php';

function svgallery_candidate(int$id):?array{return db_row('SELECT c.id,c.CampaignVersionID,c.CandidateNo,c.DisplayName,c.OptionID,v.CampaignID,ca.Status CampaignStatus FROM SafetyVote_Candidates c JOIN SafetyVote_CampaignVersions v ON v.id=c.CampaignVersionID JOIN SafetyVote_Campaigns ca ON ca.id=v.CampaignID WHERE c.id=?',[$id]);}
function svgallery_candidate_for_option(int$id):?array{return db_row("SELECT c.id,c.CampaignVersionID,c.CandidateNo,c.DisplayName,c.OptionID,v.CampaignID,ca.Status CampaignStatus FROM SafetyVote_Candidates c JOIN SafetyVote_CampaignVersions v ON v.id=c.CampaignVersionID JOIN SafetyVote_Campaigns ca ON ca.id=v.CampaignID WHERE c.OptionID=? AND c.Status IN ('Active','Finalist')",[$id]);}
function svgallery_submission(int$id):?array{return db_row('SELECT s.*,v.CampaignID VersionCampaignID FROM SafetyVote_Submissions s JOIN SafetyVote_CampaignVersions v ON v.id=s.CampaignVersionID WHERE s.id=?',[$id]);}
function svgallery_candidate_access(array$user,array$candidate):array{if(sv_role($user)==='ADMIN'||sv_has_permission($user,'SAFETY_VOTE_MANAGE')||sv_has_permission($user,'SAFETY_VOTE_SUBMISSION_REVIEW'))return['allowed'=>true,'blind'=>false];$jury=db_row("SELECT st.AdvanceRuleJson FROM SafetyVote_JuryAssignments a JOIN SafetyVote_Stages st ON st.id=a.StageID WHERE a.CampaignVersionID=? AND a.JurorEmployeeID=? AND a.Status IN ('Draft','Submitted') AND (a.CandidateID IS NULL OR a.CandidateID=?) LIMIT 1",[$candidate['CampaignVersionID'],sv_actor($user),$candidate['id']]);if($jury){$rule=json_decode((string)$jury['AdvanceRuleJson'],true);return['allowed'=>true,'blind'=>is_array($rule)&&($rule['blind']??false)===true];}if(in_array($candidate['CampaignStatus']??'',['Scheduled','Open','Closed','Certified','Published'],true)){$visible=db_row("SELECT c.id FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID WHERE c.id=? AND v.CampaignType='jury_scoring' AND c.IsHidden=0 AND c.IsTest=0 LIMIT 1",[$candidate['CampaignID']]);if($visible)return['allowed'=>true,'blind'=>false];}$eligible=db_row("SELECT e.id FROM SafetyVote_EligibilitySnapshots s JOIN SafetyVote_EligibleVoters e ON e.SnapshotID=s.id WHERE s.CampaignVersionID=? AND s.Status='frozen' AND e.EmployeeID=? LIMIT 1",[$candidate['CampaignVersionID'],sv_actor($user)]);return['allowed'=>(bool)$eligible,'blind'=>false];}
function svgallery_submission_access(array$user,array$submission):bool{return sv_role($user)==='ADMIN'||(string)$submission['SubmitterEmployeeID']===sv_actor($user)||sv_has_permission($user,'SAFETY_VOTE_SUBMISSION_REVIEW')||sv_has_permission($user,'SAFETY_VOTE_MANAGE');}
function svgallery_rows(string$ownerType,int$ownerId,bool$blind=false,?array$candidate=null):array{$rows=db_rows("SELECT g.id,g.FileID fileId,g.AltText altText,g.Caption caption,g.SortOrder sortOrder,g.IsCover isCover,f.MimeType mimeType,f.FileSize fileSize FROM SafetyVote_GalleryItems g JOIN SafetyVote_Files f ON f.id=g.FileID AND f.Status='Active' WHERE g.OwnerType=? AND g.OwnerID=? AND g.Status='Active' ORDER BY g.IsCover DESC,g.SortOrder,g.id",[$ownerType,$ownerId]);if($ownerType==='candidate'&&!empty($candidate['OptionID'])){$cover=db_row("SELECT o.FileID fileId,f.MimeType mimeType,f.FileSize fileSize FROM SafetyVote_Options o JOIN SafetyVote_Files f ON f.id=o.FileID AND f.Status='Active' WHERE o.id=? AND o.FileID IS NOT NULL",[$candidate['OptionID']]);if($cover){$exists=false;$hasCover=false;foreach($rows as$row){if((int)$row['fileId']===(int)$cover['fileId'])$exists=true;if((int)$row['isCover']===1)$hasCover=true;}if(!$exists)array_unshift($rows,array_merge(['id'=>0,'altText'=>'ภาพผลงาน '.($candidate['CandidateNo']?:$candidate['id']),'caption'=>null,'sortOrder'=>0,'isCover'=>$hasCover?0:1],$cover));}}foreach($rows as&$row){$row['id']=(int)$row['id'];$row['fileId']=(int)$row['fileId'];$row['sortOrder']=(int)$row['sortOrder'];$row['isCover']=(bool)$row['isCover'];if($blind){$row['altText']='ภาพผลงาน '.($candidate['CandidateNo']?:$candidate['id']);$row['caption']=null;}}unset($row);return$rows;}
function svgallery_store_upload(array$user,string$ownerType,array$owner,array$metadata):array{$file=$_FILES['file']??null;if(!$file||(int)$file['error']!==UPLOAD_ERR_OK||(int)$file['size']>10*1024*1024)json_response(['success'=>false,'code'=>'GALLERY_FILE_REJECTED','message'=>'A JPG, PNG or WebP image not exceeding 10 MB is required.'],400);$mime=sv_file_mime((string)$file['tmp_name']);if(!$mime||!in_array($mime,['image/jpeg','image/png','image/webp'],true))json_response(['success'=>false,'code'=>'GALLERY_FILE_REJECTED','message'=>'Image signature is invalid.'],400);$extension=['image/jpeg'=>'.jpg','image/png'=>'.png','image/webp'=>'.webp'][$mime];$stored=time().'-'.bin2hex(random_bytes(18)).$extension;$target=sv_private_dir().DIRECTORY_SEPARATOR.$stored;if(!move_uploaded_file((string)$file['tmp_name'],$target))json_response(['success'=>false,'code'=>'GALLERY_FILE_REJECTED','message'=>'Unable to store image.'],500);$campaignId=(int)($owner['CampaignID']??$owner['VersionCampaignID']);$versionId=(int)$owner['CampaignVersionID'];$ownerId=(int)$owner['id'];$pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare("SELECT COUNT(*) total,COALESCE(MAX(SortOrder),0)+1 nextOrder FROM SafetyVote_GalleryItems WHERE OwnerType=? AND OwnerID=? AND Status='Active' FOR UPDATE");$q->execute([$ownerType,$ownerId]);$count=$q->fetch();if((int)$count['total']>=SAFETY_VOTE_GALLERY_MAX_ITEMS){$pdo->rollBack();@unlink($target);json_response(['success'=>false,'code'=>'GALLERY_LIMIT_REACHED','message'=>'Gallery supports up to 12 images.'],409);}$pdo->prepare('INSERT INTO SafetyVote_Files(CampaignID,CampaignVersionID,SubmissionID,FilePurpose,StoredName,OriginalName,MimeType,FileSize,ContentSha256,UploadedBy) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$campaignId,$versionId,$ownerType==='submission'?$ownerId:null,$ownerType.'_gallery',$stored,svgallery_text($file['name']??'',255),$mime,(int)$file['size'],hash_file('sha256',$target),sv_actor($user)]);$fileId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO SafetyVote_GalleryItems(CampaignID,CampaignVersionID,OwnerType,OwnerID,FileID,AltText,Caption,SortOrder,IsCover,CreatedBy,UpdatedBy) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$campaignId,$versionId,$ownerType,$ownerId,$fileId,$metadata['altText'],$metadata['caption'],(int)$count['nextOrder'],(int)$count['total']===0?1:0,sv_actor($user),sv_actor($user)]);$itemId=(int)$pdo->lastInsertId();$pdo->commit();return['id'=>$itemId,'fileId'=>$fileId,'ownerType'=>$ownerType,'ownerId'=>$ownerId,'altText'=>$metadata['altText'],'caption'=>$metadata['caption'],'sortOrder'=>(int)$count['nextOrder'],'isCover'=>(int)$count['total']===0];}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();@unlink($target);throw$error;}}

function handle_safety_vote_gallery_routes(string$method,string$path):bool{
 $candidateList=route_params($path,'/safety-vote/admin/campaigns/:id/candidates');$candidateGet=route_params($path,'/safety-vote/gallery/candidates/:candidateId');$optionGet=route_params($path,'/safety-vote/gallery/options/:optionId');$submissionGet=route_params($path,'/safety-vote/gallery/submissions/:submissionId');$candidateUpload=route_params($path,'/safety-vote/admin/campaigns/:id/candidates/:candidateId/gallery');$submissionUpload=route_params($path,'/safety-vote/submissions/:submissionId/gallery');$ownerUpdate=route_params($path,'/safety-vote/gallery/:ownerType/:ownerId');$itemDelete=route_params($path,'/safety-vote/gallery/items/:itemId');
 if(!$candidateList&&!$candidateGet&&!$optionGet&&!$submissionGet&&!$candidateUpload&&!$submissionUpload&&!$ownerUpdate&&!$itemDelete)return false;$user=require_user();$health=sv_require_schema();if(empty($health['capabilities']['candidateSubmissionGallery']))json_response(['success'=>false,'code'=>'GALLERY_SETUP_REQUIRED','message'=>'Candidate and submission gallery migration is required.'],503);
 $galleryAction=null;$gallerySubmission=null;if($submissionUpload&&$method==='POST'){$galleryAction='submission_gallery_upload';$gallerySubmission=svgallery_submission((int)$submissionUpload['submissionId']);}elseif($ownerUpdate&&$method==='PUT'&&($ownerUpdate['ownerType']??'')==='submission'){$galleryAction='submission_gallery_update';$gallerySubmission=svgallery_submission((int)$ownerUpdate['ownerId']);}elseif($itemDelete&&$method==='DELETE'){$galleryItem=db_row("SELECT OwnerType,OwnerID FROM SafetyVote_GalleryItems WHERE id=? AND Status='Active'",[(int)$itemDelete['itemId']]);if(($galleryItem['OwnerType']??'')==='submission'){$galleryAction='submission_gallery_remove';$gallerySubmission=svgallery_submission((int)$galleryItem['OwnerID']);}}if($galleryAction){$galleryCampaign=$gallerySubmission?sv2_campaign((int)($gallerySubmission['CampaignID']??$gallerySubmission['VersionCampaignID'])):null;$galleryEligible=$galleryCampaign?db_row("SELECT e.id FROM SafetyVote_EligibilitySnapshots s JOIN SafetyVote_EligibleVoters e ON e.SnapshotID=s.id WHERE s.id=(SELECT id FROM SafetyVote_EligibilitySnapshots WHERE CampaignVersionID=? AND Status='frozen' ORDER BY SnapshotNo DESC,id DESC LIMIT 1) AND e.EmployeeID=? AND e.EligibilityState='eligible' LIMIT 1",[$galleryCampaign['CurrentVersionID'],sv_actor($user)]):null;svpa_require(['action'=>$galleryAction,'campaign'=>$galleryCampaign,'eligible'=>(bool)$galleryEligible,'owner'=>(bool)($gallerySubmission&&(string)$gallerySubmission['SubmitterEmployeeID']===sv_actor($user)),'resourceVersionId'=>(int)($gallerySubmission['CampaignVersionID']??0)]);}
