 if($candidateGet&&$method==='GET'){$candidate=svgallery_candidate((int)$candidateGet['candidateId']);if(!$candidate)json_response(['success'=>false,'code'=>'CANDIDATE_NOT_FOUND'],404);$access=svgallery_candidate_access($user,$candidate);if(!$access['allowed'])json_response(['success'=>false,'code'=>'GALLERY_ACCESS_DENIED'],403);json_response(['success'=>true,'data'=>['ownerType'=>'candidate','ownerId'=>(int)$candidate['id'],'blind'=>$access['blind'],'items'=>svgallery_rows('candidate',(int)$candidate['id'],$access['blind'],$candidate)]]);}
 if($optionGet&&$method==='GET'){$optionId=svgallery_int($optionGet['optionId']);if(!$optionId)json_response(['success'=>false,'code'=>'OPTION_NOT_FOUND'],404);$candidate=svgallery_candidate_for_option($optionId);if(!$candidate)json_response(['success'=>true,'data'=>['ownerType'=>'candidate','ownerId'=>null,'optionId'=>$optionId,'candidateBacked'=>false,'blind'=>false,'items'=>[]]]);$access=svgallery_candidate_access($user,$candidate);if(!$access['allowed'])json_response(['success'=>false,'code'=>'GALLERY_ACCESS_DENIED'],403);json_response(['success'=>true,'data'=>['ownerType'=>'candidate','ownerId'=>(int)$candidate['id'],'optionId'=>(int)$candidate['OptionID'],'candidateBacked'=>true,'blind'=>$access['blind'],'items'=>svgallery_rows('candidate',(int)$candidate['id'],$access['blind'],$candidate)]]);}
 if($submissionGet&&$method==='GET'){$submission=svgallery_submission((int)$submissionGet['submissionId']);if(!$submission)json_response(['success'=>false,'code'=>'SUBMISSION_NOT_FOUND'],404);if(!svgallery_submission_access($user,$submission))json_response(['success'=>false,'code'=>'GALLERY_ACCESS_DENIED'],403);json_response(['success'=>true,'data'=>['ownerType'=>'submission','ownerId'=>(int)$submission['id'],'items'=>svgallery_rows('submission',(int)$submission['id'])]]);}
 if($candidateUpload&&$method==='POST'){sv_require_permission($user,'SAFETY_VOTE_MANAGE');$candidate=svgallery_candidate((int)$candidateUpload['candidateId']);if(!$candidate)json_response(['success'=>false,'code'=>'CANDIDATE_NOT_FOUND'],404);if((int)$candidate['CampaignID']!==(int)$candidateUpload['id']||$candidate['CampaignStatus']!=='Draft')json_response(['success'=>false,'code'=>'CAMPAIGN_STATE_CONFLICT'],409);$meta=svgallery_metadata($_POST);if(!$meta['ok'])json_response(['success'=>false,'code'=>'ALT_TEXT_REQUIRED'],400);$item=svgallery_store_upload($user,'candidate',$candidate,$meta['value']);sv_audit($user,'SAFETY_VOTE_CANDIDATE_GALLERY_UPLOAD','SafetyVote_GalleryItem',(string)$item['id'],'candidate='.(int)$candidate['id'],['fileId'=>$item['fileId']],(int)$candidate['CampaignID'],(int)$candidate['CampaignVersionID']);json_response(['success'=>true,'data'=>$item],201);}
 if($submissionUpload&&$method==='POST'){$submission=svgallery_submission((int)$submissionUpload['submissionId']);if(!$submission)json_response(['success'=>false,'code'=>'SUBMISSION_NOT_FOUND'],404);if((string)$submission['SubmitterEmployeeID']!==sv_actor($user)||!in_array($submission['Status'],['Draft','RevisionRequested'],true))json_response(['success'=>false,'code'=>'SUBMISSION_STATE_CONFLICT'],409);$meta=svgallery_metadata($_POST);if(!$meta['ok'])json_response(['success'=>false,'code'=>'ALT_TEXT_REQUIRED'],400);$item=svgallery_store_upload($user,'submission',$submission,$meta['value']);sv_audit($user,'SAFETY_VOTE_SUBMISSION_GALLERY_UPLOAD','SafetyVote_GalleryItem',(string)$item['id'],'submission='.(int)$submission['id'],['fileId'=>$item['fileId']],(int)$submission['CampaignID'],(int)$submission['CampaignVersionID']);json_response(['success'=>true,'data'=>$item],201);}
 if($ownerUpdate&&$method==='PUT'){$ownerType=(string)$ownerUpdate['ownerType'];$ownerId=svgallery_int($ownerUpdate['ownerId']);if(!in_array($ownerType,['candidate','submission'],true)||!$ownerId)json_response(['success'=>false,'code'=>'VALIDATION_FAILED'],400);$parsed=svgallery_reorder(json_body()['items']??null);if(!$parsed['ok'])json_response(['success'=>false,'code'=>'VALIDATION_FAILED','details'=>$parsed['errors']],400);$owner=$ownerType==='candidate'?svgallery_candidate($ownerId):svgallery_submission($ownerId);if(!$owner)json_response(['success'=>false,'code'=>'GALLERY_OWNER_NOT_FOUND'],404);$editable=$ownerType==='candidate'?(sv_has_permission($user,'SAFETY_VOTE_MANAGE')&&$owner['CampaignStatus']==='Draft'):((string)$owner['SubmitterEmployeeID']===sv_actor($user)&&in_array($owner['Status'],['Draft','RevisionRequested'],true));if(!$editable)json_response(['success'=>false,'code'=>'GALLERY_STATE_CONFLICT'],409);$existing=db_rows("SELECT id FROM SafetyVote_GalleryItems WHERE OwnerType=? AND OwnerID=? AND Status='Active'",[$ownerType,$ownerId]);$ids=array_column($parsed['items'],'id');if(count($existing)!==count($ids)||array_diff(array_map('intval',array_column($existing,'id')),$ids))json_response(['success'=>false,'code'=>'GALLERY_VERSION_CONFLICT'],409);$pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare("UPDATE SafetyVote_GalleryItems SET AltText=?,Caption=?,SortOrder=?,IsCover=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=? AND OwnerType=? AND OwnerID=? AND Status='Active'");foreach($parsed['items']as$item)$q->execute([$item['altText'],$item['caption'],$item['sortOrder'],$item['isCover']?1:0,sv_actor($user),$item['id'],$ownerType,$ownerId]);sv_audit($user,'SAFETY_VOTE_GALLERY_REORDER','SafetyVote_GalleryOwner',$ownerType.':'.$ownerId,'items='.count($parsed['items']),['ownerType'=>$ownerType],(int)($owner['CampaignID']??$owner['VersionCampaignID']),(int)$owner['CampaignVersionID']);$pdo->commit();json_response(['success'=>true,'data'=>['ownerType'=>$ownerType,'ownerId'=>$ownerId,'items'=>svgallery_rows($ownerType,$ownerId,false,$ownerType==='candidate'?$owner:null),'serverConfirmed'=>true]]);}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();json_response(['success'=>false,'code'=>'GALLERY_SAVE_FAILED'],500);}}
 if($itemDelete&&$method==='DELETE'){$item=db_row("SELECT g.*,s.SubmitterEmployeeID,s.Status SubmissionStatus,ca.Status CampaignStatus FROM SafetyVote_GalleryItems g LEFT JOIN SafetyVote_Submissions s ON g.OwnerType='submission' AND s.id=g.OwnerID LEFT JOIN SafetyVote_Campaigns ca ON ca.id=g.CampaignID WHERE g.id=? AND g.Status='Active'",[(int)$itemDelete['itemId']]);if(!$item)json_response(['success'=>false,'code'=>'GALLERY_ITEM_NOT_FOUND'],404);$editable=$item['OwnerType']==='candidate'?(sv_has_permission($user,'SAFETY_VOTE_MANAGE')&&$item['CampaignStatus']==='Draft'):((string)$item['SubmitterEmployeeID']===sv_actor($user)&&in_array($item['SubmissionStatus'],['Draft','RevisionRequested'],true));if(!$editable)json_response(['success'=>false,'code'=>'GALLERY_STATE_CONFLICT'],409);$pdo=db();$pdo->beginTransaction();try{$pdo->prepare("UPDATE SafetyVote_GalleryItems SET Status='Removed',UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=? AND Status='Active'")->execute([sv_actor($user),$item['id']]);$pdo->prepare("UPDATE SafetyVote_Files SET Status='Removed',RemovedBy=?,RemovedAt=NOW(),RemovalReason='Removed from gallery' WHERE id=? AND Status='Active'")->execute([sv_actor($user),$item['FileID']]);sv_audit($user,'SAFETY_VOTE_GALLERY_REMOVE','SafetyVote_GalleryItem',(string)$item['id'],'owner='.$item['OwnerType'].':'.$item['OwnerID'],['fileId'=>(int)$item['FileID']],(int)$item['CampaignID'],(int)$item['CampaignVersionID']);$pdo->commit();json_response(['success'=>true,'data'=>['id'=>(int)$item['id'],'removed'=>true,'serverConfirmed'=>true]]);}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();json_response(['success'=>false,'code'=>'GALLERY_REMOVE_FAILED'],500);}}
 return false;
